void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    const size_t size = x.size();
    const size_t simd_width = 8; // Number of elements processed per SIMD iteration

    // Initialize bins to zero
    for (size_t i = 0; i < 10; ++i) {
        bins[i] = 0;
    }

    // Process elements in chunks using SIMD
    for (size_t i = 0; i < size; i += simd_width) {
        __m256d data_vec = _mm256_loadu_pd(&x[i]);
        __m256i bin_vec = _mm256_srai_epi32(_mm256_slli_epi32(_mm256_cvttpd_epi32(data_vec), 7), 3);
        int bin_counts[8];
        _mm256_storeu_si256((__m256i*)bin_counts, bin_vec);

        // Update bins based on SIMD results
        for (size_t j = 0; j < simd_width; ++j) {
            if (i + j < size) {
                bins[bin_counts[j]]++;
            }
        }
    }

    // Process remaining elements
    for (size_t i = size - (size % simd_width); i < size; ++i) {
        const size_t bin = x[i] / 10;
        bins[bin]++;
    }
}

