#pragma once

#include <vector>
#include <cmath>

void mapPowersOfTwo(std::vector<int> const& x, std::vector<bool> &mask) {
    // Precompute powers of 2 up to the maximum value in x
    int maxVal = *std::max_element(x.begin(), x.end());
    int maxPower = (int)std::log2(maxVal);
    std::vector<int> powersOfTwo(maxPower + 1);
    powersOfTwo[0] = 1;
    for (int i = 1; i <= maxPower; ++i) {
        powersOfTwo[i] = powersOfTwo[i - 1] * 2;
    }

    // Use a bitwise AND operation to check if each number is a power of 2
    for (int i = 0; i < x.size(); ++i) {
        int val = x[i];
        int power = (int)std::log2(val);
        mask[i] = (val == powersOfTwo[power]);
    }
}

#pragma once

#include <vector>
#include <cmath>

void mapPowersOfTwo(std::vector<int> const& x, std::vector<bool> &mask) {
    int n = x.size();
    mask.resize(n);

    // Precompute powers of 2 up to the maximum value in x
    int maxVal = *std::max_element(x.begin(), x.end());
    int maxPower = (int)std::log2(maxVal);
    std::vector<bool> isPowerOfTwo(maxVal + 1, false);
    for (int i = 0; i <= maxPower; i++) {
        isPowerOfTwo[1 << i] = true;
    }

    // Map x to mask using precomputed powers of 2
    for (int i = 0; i < n; i++) {
        mask[i] = isPowerOfTwo[x[i]];
    }
}

