#pragma once
#include <vector>
#include <immintrin.h>

void oneMinusInverse(std::vector<double> &x) {
    const size_t size = x.size();
    const size_t simd_width = 4; // Number of doubles processed simultaneously using SIMD
    const size_t remainder = size % simd_width;

    // Loop unrolling and SIMD optimization
    for (size_t i = 0; i < size - remainder; i += simd_width) {
        __m256d data = _mm256_loadu_pd(&x[i]);
        __m256d inv = _mm256_rcp_pd(data);
        __m256d result = _mm256_sub_pd(_mm256_set1_pd(1.0), inv);
        _mm256_storeu_pd(&x[i], result);
    }

    // Process remaining elements individually
    for (size_t i = size - remainder; i < size; ++i) {
        x[i] = 1.0 - 1.0 / x[i];
    }
}

