void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
   // Pre-allocate memory for L and U
   L.resize(N * N);
   U.resize(N * N);

   // Initialize L and U to zero
   for (size_t i = 0; i < N * N; ++i) {
      L[i] = 0.0;
      U[i] = 0.0;
   }

   // Fill in L and U based on the given COO matrix
   for (const auto& element : A) {
      size_t row = element.row;
      size_t col = element.column;
      double value = element.value;

      // Fill in L
      if (row == col) {
         L[row * N + col] = 1.0;  // Diagonal element is 1
      } else if (row < col) {
         L[row * N + col] = value;  // Lower triangle
      }

      // Fill in U
      if (row <= col) {
         U[row * N + col] = value;  // Upper triangle
      }
   }

   // Perform LU factorization
   for (size_t j = 0; j < N; ++j) {
      for (size_t i = j + 1; i < N; ++i) {
         double l_ij = L[i * N + j];
         for (size_t k = 0; k < j; ++k) {
            l_ij -= L[i * N + k] * U[k * N + j];
         }
         L[i * N + j] = l_ij;
      }

      for (size_t i = j; i < N; ++i) {
         double u_ij = U[j * N + i];
         for (size_t k = 0; k < j; ++k) {
            u_ij -= L[j * N + k] * U[k * N + i];
         }
         U[j * N + i] = u_ij / L[j * N + j];
      }
   }
}

