#pragma once
#include <vector>
#include <numeric>
#include <immintrin.h>

double productWithInverses(std::vector<double> const& x) {
    double result = 1.0;
    size_t size = x.size();
    size_t i = 0;

    // Process 4 elements at a time using SIMD
    for (; i + 4 <= size; i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
