*/
void fft(std::vector<std::complex<double>> const& x, std::vector<double> &r, std::vector<double> &i) {
    std::vector<std::complex<double>> x_copy = x;
    unsigned int N = x_copy.size();
    if (N == 1) {
        r[0] = x_copy[0].real();
        i[0] = x_copy[0].imag();
        return;
    }

    std::vector<std::complex<double>> even(N / 2);
    std::vector<std::complex<double>> odd(N / 2);
    for (unsigned int i = 0; i < N / 2; i++) {
        even[i] = x_copy[2 * i];
        odd[i] = x_copy[2 * i + 1];
    }

    std::vector<double> r_even(N / 2);
    std::vector<double> i_even(N / 2);
    std::vector<double> r_odd(N / 2);
    std::vector<double> i_odd(N / 2);
    fft(even, r_even, i_even);
    fft(odd, r_odd, i_odd);

    double angle = 2 * M_PI / N;
    std::complex<double> w(1);
    std::complex<double> wn(cos(angle), sin(angle));
    for (unsigned int k = 0; k < N / 2; k++) {
        r[k] = r_even[k] + w.real() * r_odd[k] - w.imag() * i_odd[k];
        i[k] = i_even[k] + w.real() * i_odd[k] + w.imag() * r_odd[k];
        r[k + N / 2] = r_even[k] - w.real() * r_odd[k] + w.imag() * i_odd[k];
        i[k + N / 2] = i_even[k] - w.real() * i_odd[k] - w.imag() * r_odd[k];
