bool compare(const Point& a, const Point& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

bool cross(const Point& a, const Point& b, const Point& c) {
    return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x) > 0;
}

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3) {
        hull = points;
        return;
    }

    std::vector<Point> pointsSorted = points;
    std::sort(pointsSorted.begin(), pointsSorted.end(), compare);

    std::vector<Point> upperHull;
    std::vector<Point> lowerHull;
    upperHull.reserve(pointsSorted.size());
    lowerHull.reserve(pointsSorted.size());

    for (size_t i = 0; i < pointsSorted.size(); ++i) {
        while (upperHull.size() >= 2 &&!cross(upperHull[upperHull.size() - 2], upperHull.back(), pointsSorted[i])) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);
    }

    for (int i = pointsSorted.size() - 1; i >= 0; --i) {
        while (lowerHull.size() >= 2 &&!cross(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[i])) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[i]);
    }

    // Remove the last point of each hull (it's the same as the first)
    upperHull.pop_back();
    lowerHull.pop_back();

    // Concatenate the upper and lower hulls
    hull.reserve(upperHull.size() + lowerHull.size());
    hull.insert(hull.end(), upperHull.begin(), upperHull.end());
    // Reverse the lower hull and add it without the first and last points
    std::reverse(lowerHull.begin(), lowerHull.end());
    hull.insert(hull.end(), lowerHull.begin() + 1, lowerHull.end() - 1);
}

