/* Find the set of points that defined the smallest convex polygon that contains all the points in the vector points. Store the result in `hull`.
   Example:

   input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
   output: [{0, 3}, {4, 4}, {3, 1}, {0, 0}]
*/
void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    std::vector<Point> pointsSorted = points;

    // Sort points by x-coordinate, then by y-coordinate
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Helper function to calculate the cross product of two vectors
    auto CrossProduct = [](Point const& a, Point const& b, Point const& c) {
        return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x);
    };

    std::vector<Point> upperHull;
    std::vector<Point> lowerHull;
    upperHull.reserve(pointsSorted.size());
    lowerHull.reserve(pointsSorted.size());

    // Build the upper and lower hulls
    for (size_t i = 0; i < pointsSorted.size(); i++) {
        // Build the upper hull
        while (upperHull.size() >= 2 && CrossProduct(upperHull[upperHull.size() - 2], upperHull.back(), pointsSorted[i]) <= 0) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);

        // Build the lower hull
        while (lowerHull.size() >= 2 && CrossProduct(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[pointsSorted.size() - i - 1]) >= 0) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[pointsSorted.size() - i - 1]);
    }

    // Combine the upper and lower hulls to get the convex hull
    hull.reserve(upperHull.size() + lowerHull.size() - 2);
    hull.insert(hull.end(), upperHull.begin(), upperHull.end());
    for (size_t i = lowerHull.size() - 2; i > 0; --i) {
        hull.push_back(lowerHull[i]);
    }
}

