    upperHull.push_back(pointsSorted[0]);
    upperHull.push_back(pointsSorted[1]);
    for (size_t i = 2; i < pointsSorted.size(); ++i) {
        while (upperHull.size() > 1
               && CrossProduct(upperHull[upperHull.size() - 2], upperHull.back(), pointsSorted[i]) <= 0) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);
    }

    // Build the lower hull
    lowerHull.push_back(pointsSorted[pointsSorted.size() - 1]);
    lowerHull.push_back(pointsSorted[pointsSorted.size() - 2]);
    for (int i = pointsSorted.size() - 3; i >= 0; --i) {
        while (lowerHull.size() > 1
               && CrossProduct(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[i]) <= 0) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[i]);
    }

    // Concatenate the upper and lower hulls
    upperHull.insert(upperHull.end(), lowerHull.begin(), lowerHull.end());
