#include <vector>
#include <algorithm>

/* Find the set of points that defined the smallest convex polygon that contains all the points in the vector points. Store the result in `hull`.
   Example:

   input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
   output: [{0, 3}, {4, 4}, {3, 1}, {0, 0}]
*/
void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    std::vector<Point> pointsSorted = points;
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    hull.reserve(pointsSorted.size() * 2);

    // Build the upper hull
    hull.push_back(pointsSorted[0]);
    hull.push_back(pointsSorted[1]);
    for (size_t i = 2; i < pointsSorted.size(); i++) {
        hull.push_back(pointsSorted[i]);
        while (hull.size() >= 3 &&!isLeftTurn(hull[hull.size() - 3], hull[hull.size() - 2], hull.back())) {
            hull.erase(hull.end() - 2);
        }
    }

    // Build the lower hull
    size_t startIndex = hull.size();
    for (size_t i = pointsSorted.size() - 2; i > 0; i--) {
        hull.push_back(pointsSorted[i]);
        while (hull.size() >= startIndex + 2 &&!isLeftTurn(hull[hull.size() - 3], hull[hull.size() - 2], hull.back())) {
            hull.erase(hull.end() - 2);
        }
    }

    // Remove duplicates
    std::sort(hull.begin(), hull.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    hull.erase(std::unique(hull.begin(), hull.end(), [](Point const& a, Point const& b) {
        return a.x == b.x && a.y == b.y;
    }), hull.end());
}

bool isLeftTurn(Point const& a, Point const& b, Point const& c) {
    return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x) > 0;
}

