/* Find the set of points that defined the smallest convex polygon that contains all the points in the vector points. Store the result in `hull`.
   Example:

   input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
   output: [{0, 3}, {4, 4}, {3, 1}, {0, 0}]
*/
void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    std::vector<Point> pointsSorted = points;

    // Sort the points by their x-coordinates, and break ties by their y-coordinates
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Helper function to compute the cross product of two vectors (a - p) and (b - p)
    auto CrossProduct = [](Point const& a, Point const& b, Point const& p) {
        return (b.x - p.x) * (a.y - p.y) - (b.y - p.y) * (a.x - p.x);
    };

    // Compute the upper hull
    std::vector<Point> upperHull;
    upperHull.reserve(pointsSorted.size()); // Reserve space to avoid reallocations
    for (size_t i = 0; i < pointsSorted.size(); ++i) {
        while (upperHull.size() >= 2 && CrossProduct(upperHull[upperHull.size() - 2], upperHull.back(), pointsSorted[i]) <= 0) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);
    }

    // Compute the lower hull
    std::vector<Point> lowerHull;
    lowerHull.reserve(pointsSorted.size()); // Reserve space to avoid reallocations
    for (int i = pointsSorted.size() - 1; i >= 0; --i) {
        while (lowerHull.size() >= 2 && CrossProduct(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[i]) <= 0) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[i]);
    }

    // Combine the upper and lower hulls to get the convex hull
    hull.reserve(upperHull.size() + lowerHull.size() - 2); // Reserve space to avoid reallocations
    std::move(upperHull.begin(), upperHull.end(), std::back_inserter(hull));
    // Remove the first and last points of the lower hull (which are the same as the first and last points of the upper hull)
    lowerHull.erase(lowerHull.begin());
    lowerHull.pop_back();
    std::move(lowerHull.begin(), lowerHull.end(), std::back_inserter(hull));
}

