struct Point {
    double x, y;
};

bool comparePoints(const Point& a, const Point& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

bool crossProduct(const Point& a, const Point& b, const Point& c) {
    return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x) > 0;
}

void convexHull(std::vector<Point> const& points, std::vector<Point>& hull) {
    if (points.size() < 3) {
        hull = points;
        return;
    }

    std::vector<Point> pointsSorted = points;
    std::sort(pointsSorted.begin(), pointsSorted.end(), comparePoints);

    std::vector<Point> upperHull;
    std::vector<Point> lowerHull;
    upperHull.reserve(pointsSorted.size());
    lowerHull.reserve(pointsSorted.size());

    for (size_t i = 0; i < pointsSorted.size(); ++i) {
        while (upperHull.size() >= 2 &&!crossProduct(upperHull[upperHull.size() - 2], upperHull.back(), pointsSorted[i])) {
            upperHull.pop_back();
        }
        upperHull.push_back(pointsSorted[i]);

        while (lowerHull.size() >= 2 &&!crossProduct(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[pointsSorted.size() - i - 1])) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[pointsSorted.size() - i - 1]);
    }

    upperHull.insert(upperHull.end(), lowerHull.rbegin() + 1, lowerHull.rend());
    hull = upperHull;
}

