    }

    std::vector<Point> pointsSorted = points;
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    hull.reserve(pointsSorted.size());

    // Build the upper hull
    hull.push_back(pointsSorted[0]);
    hull.push_back(pointsSorted[1]);
    for (size_t i = 2; i < pointsSorted.size(); ++i) {
        while (hull.size() > 1 && CrossProduct(hull[hull.size() - 2], hull[hull.size() - 1], pointsSorted[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(pointsSorted[i]);
    }

    // Build the lower hull
    size_t startingIndex = hull.size();
    for (size_t i = pointsSorted.size() - 2; i >= 2; --i) {
        while (hull.size() > startingIndex && CrossProduct(hull[hull.size() - 2], hull[hull.size() - 1], pointsSorted[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(pointsSorted[i]);
    }

    // Remove duplicates
    hull.erase(std::unique(hull.begin(), hull.end()), hull.end());
}

int CrossProduct(Point const& a, Point const& b, Point const& c) {
    return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x);
}

