void jacobi1D(std::vector<double> const& input, std::vector<double> &output) {
    size_t size = input.size();
    size_t i = 0;

    // Process first two elements separately
    if (size > 0) output[0] = (input[0] + input[1]) * 0.5;
    if (size > 1) output[1] = (input[0] + input[1] + input[2]) * 0.3333333333333333;
    i = 2;

    // Process 4 elements at a time using SIMD
    for (; i + 4 <= size; i += 4) {
        __m256d in = _mm256_loadu_pd(&input[i]);
        __m256d sum = _mm256_set1_pd(input[i - 1]) + in + _mm256_set1_pd(input[i + 1]);
        _mm256_storeu_pd(&output[i], sum * (1.0 / 3.0));
    }

    // Process remaining elements
    for (; i < size; i++) {
        double sum = input[i - 1] + input[i] + input[i + 1];
        output[i] = sum * 0.3333333333333333;
    }
}

