#pragma once
#include <vector>
#include <immintrin.h>

void cellsXOR(std::vector<int> const& input, std::vector<int> &output, size_t N) {
    for (size_t i = 0; i < N; i += 4) {
        for (size_t j = 0; j < N; j += 4) {
            __m256i counts = _mm256_setzero_si256();

            // Process 4x4 block
            for (size_t k = 0; k < 4; ++k) {
                size_t row = i + k;
                if (row > 0) {
                    __m256i top_row = _mm256_loadu_si256((__m256i*)&input[(row-1)*N + j]);
                    counts = _mm256_add_epi32(counts, _mm256_and_si256(_mm256_slli_epi32(top_row, 1), top_row));
                }
                if (row < N-1) {
                    __m256i bottom_row = _mm256_loadu_si256((__m256i*)&input[(row+1)*N + j]);
                    counts = _mm256_add_epi32(counts, _mm256_and_si256(_mm256_srli_epi32(bottom_row, 1), bottom_row));
                }
                if (j > 0) {
                    __m256i left_col = _mm256_loadu_si256((__m256i*)&input[row*N + j-1]);
                    counts = _mm256_add_epi32(counts, _mm256_and_si256(_mm256_slli_epi32(left_col, 1), left_col));
                }
                if (j < N-1) {
                    __m256i right_col = _mm256_loadu_si256((__m256i*)&input[row*N + j+1]);
                    counts = _mm256_add_epi32(counts, _mm256_and_si256(_mm256_srli_epi32(right_col, 1), right_col));
                }
            }

            // Store results
            for (size_t k = 0; k < 4; ++k) {
                size_t row = i + k;
                __m256i result = _mm256_slli_epi32(_mm256_cmpeq_epi32(counts, _mm256_set1_epi32(1)), 1);
                _mm256_storeu_si256((__m256i*)&output[row*N + j], result);
            }
        }
    }

    // Handle remaining rows and columns
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            int count = 0;
            if (i > 0 && input[(i-1)*N + j] == 1) ++count;
            if (i < N-1 && input[(i+1)*N + j] == 1) ++count;
            if (j > 0 && input[i*N + j-1] == 1) ++count;
            if (j < N-1 && input[i*N + j+1] == 1) ++count;
            output[i*N + j] = (count == 1)? 1 : 0;
        }
    }
}

