                sum += input[i * N + j]; // Handle boundary condition
            }
            if (j > 0) {
                sum += input[i * N + (j - 1)];
            } else {
                sum += input[i * N + j]; // Handle boundary condition
            }
            if (j < N - 1) {
                sum += input[i * N + (j + 1)];
            } else {
                sum += input[i * N + j]; // Handle boundary condition
            }
            sum += input[i * N + j];
            output[i * N + j] = sum / 5.0;
        }
    }
