// Use SIMD to process multiple elements simultaneously
void jacobi2D_simd(std::vector<double> const& input, std::vector<double> &output, size_t N) {
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j += 4) { // Process 4 elements at a time using SIMD
            __m256d in_vec = _mm256_loadu_pd(&input[i * N + j]);
            __m256d sum_vec = _mm256_setzero_pd();

            // Handle boundary conditions for leftmost element
            if (j > 0) {
                __m256d left_vec = _mm256_loadu_pd(&input[i * N + j - 1]);
                sum_vec = _mm256_add_pd(sum_vec, left_vec);
            } else {
                __m256d left_vec = _mm256_set1_pd(input[i * N + j]); // Replicate the current element
                sum_vec = _mm256_add_pd(sum_vec, left_vec);
            }

            // Handle boundary conditions for rightmost element
            if (j + 3 < N) {
                __m256d right_vec = _mm256_loadu_pd(&input[i * N + j + 1]);
                sum_vec = _mm256_add_pd(sum_vec, right_vec);
            } else {
                __m256d right_vec = _mm256_set1_pd(input[i * N + j]); // Replicate the current element
                sum_vec = _mm256_add_pd(sum_vec, right_vec);
            }

            // Handle boundary conditions for top element
            if (i > 0) {
                __m256d top_vec = _mm256_loadu_pd(&input[(i - 1) * N + j]);
                sum_vec = _mm256_add_pd(sum_vec, top_vec);
            } else {
                __m256d top_vec = _mm256_set1_pd(input[i * N + j]); // Replicate the current element
                sum_vec = _mm256_add_pd(sum_vec, top_vec);
            }

            // Handle boundary conditions for bottom element
            if (i + 1 < N) {
                __m256d bottom_vec = _mm256_loadu_pd(&input[(i + 1) * N + j]);
                sum_vec = _mm256_add_pd(sum_vec, bottom_vec);
            } else {
                __m256d bottom_vec = _mm256_set1_pd(input[i * N + j]); // Replicate the current element
                sum_vec = _mm256_add_pd(sum_vec, bottom_vec);
            }

            // Add the current element to the sum
            sum_vec = _mm256_add_pd(sum_vec, in_vec);

            // Store the result back to the output vector
            _mm256_storeu_pd(&output[i * N + j], _mm256_div_pd(sum_vec, _mm256_set1_pd(5.0)));
        }
    }
}

