void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    for (size_t i = 0; i < M; i++) {
        y[i] = 0;
        size_t j = 0;
        for (; j + 4 < N; j += 4) {
            __m256d a_vec = _mm256_loadu_pd(&A[i * N + j]);
            __m256d x_vec = _mm256_loadu_pd(&x[j]);
            __m256d prod = _mm256_mul_pd(a_vec, x_vec);
            __m256d sum = _mm256_hadd_pd(prod, prod);
            __m128d sum_low = _mm256_castpd256_pd128(sum);
            __m128d sum_high = _mm256_extractf128_pd(sum, 1);
            __m128d final_sum = _mm_add_pd(sum_low, sum_high);
            double partial_sum[2];
            _mm_store_pd(partial_sum, final_sum);
            y[i] += partial_sum[0] + partial_sum[1];
        }
        for (; j < N; j++) {
            y[i] += A[i * N + j] * x[j];
        }
    }
}

