            __m128d sum_high = _mm256_extractf128_pd(sum, 1);
            sum_low = _mm_add_pd(sum_low, sum_high);
            double partial_sum[2];
            _mm_store_pd(partial_sum, sum_low);
            y[i] += partial_sum[0] + partial_sum[1];
        }
        for (; j < N; j++) {
            y[i] += A[i * N + j] * x[j];
        }
