void ranks(std::vector<float> const& x, std::vector<size_t> &ranks_) {
    std::vector<size_t> indices(x.size());
    for (size_t i = 0; i < x.size(); ++i) {
        indices[i] = i;
    }

    // Sort indices based on corresponding values in x
    std::sort(indices.begin(), indices.end(), [&x](size_t i1, size_t i2) {
        return x[i1] < x[i2];
    });

    // Parallelly update ranks_ based on sorted indices
    cilk_for (size_t i = 0; i < x.size(); ++i) {
        ranks_[indices[i]] = i;
    }
